-- Project information (content is JSON rendered by proyecto.html).

INSERT OR IGNORE INTO project_info (section_key, title, content)
VALUES ('what_is', 'La energía en manos de las comunidades.', '{"eyebrow": "QUÉ SON LAS ENERGÍAS COMUNITARIAS", "paragraphs": ["Las energías comunitarias comprenden iniciativas impulsadas y gestionadas por comunidades y organizaciones locales que promueven modelos energéticos más justos, participativos, sostenibles y autónomos. Ante la crisis climática y las desigualdades energéticas, ofrecen alternativas para construir futuros energéticos desde las comunidades.", "Este mapeo reúne experiencias relevantes para América Latina y el Caribe. Es un proceso dinámico y en constante construcción que busca identificar, visibilizar y conectar experiencias que inspiren e impulsen alternativas energéticas comunitarias en la región."], "list_title": "Dimensiones que considera el mapeo", "list": ["Justicia social y ambiental", "Defensa territorial", "Adaptación climática", "Autosuficiencia", "Sostenibilidad", "Replicabilidad"]}');

INSERT OR IGNORE INTO project_info (section_key, title, content)
VALUES ('scope', 'Distintas formas de responder a prioridades colectivas.', '{"eyebrow": "ALCANCE", "items": [{"title": "Energía para hogares y comunidades", "text": "Iniciativas que energizan hogares y comunidades, atendiendo sus necesidades locales."}, {"title": "Renovables y espacios comunitarios", "text": "Instalación de sistemas de energía renovable y energización de espacios públicos y comunitarios."}, {"title": "Movilidad y economía local", "text": "Propuestas vinculadas al transporte sostenible y al fortalecimiento de negocios y emprendimientos locales."}], "note": "En conjunto, estas propuestas muestran distintas posibilidades de utilizar la energía para fortalecer la autonomía y el bienestar comunitario."}');

INSERT OR IGNORE INTO project_info (section_key, title, content)
VALUES ('vision', 'Una transición energética que repare deudas históricas.', '{"eyebrow": "VISIÓN", "paragraphs": ["Imaginamos países donde las comunidades poseen, gobiernan y sostienen su propia energía; donde la luz no llega como un servicio concedido desde afuera, sino como una decisión tomada por el consejo, la cooperativa o el barrio.", "Los territorios que menos energía han recibido y que más han cargado con los costos de la extracción pasan a liderar el cambio. La transición energética repara deudas históricas en lugar de repetirlas."]}');

INSERT OR IGNORE INTO project_info (section_key, title, content)
VALUES ('purpose', 'Visibilizar e impulsar la democratización de la energía.', '{"eyebrow": "PROPÓSITO", "items": [{"title": "Dar visibilidad a las energías comunitarias", "text": "Estas experiencias existen, funcionan y casi no se cuentan. Las reunimos en un recorrido narrativo para que el público, los financiadores y quienes diseñan políticas las reconozcan como un modelo real, no como casos aislados."}, {"title": "Impulsar la democratización de la energía", "text": "Democratizar no es solo llevar electricidad a más lugares: es poner el territorio y la decisión en manos de la comunidad. Cada historia muestra una forma de hacerlo y comparte aprendizajes que otros territorios pueden adaptar."}]}');

INSERT OR IGNORE INTO project_info (section_key, title, content)
VALUES ('categories', 'Criterios para seleccionar y contar las experiencias.', '{"eyebrow": "CATEGORÍAS", "note": "Cinco categorías guían qué experiencias entran en el proyecto y cómo se cuentan. Según el marco de selección del equipo, se asigna 1 si el esfuerzo cumple el criterio y 0 si no lo cumple o no hay información.", "items": [{"title": "Justicia energética", "text": "Atiende la desigualdad en el acceso a la energía y reparte de forma justa sus beneficios y la capacidad de decidir sobre ella."}, {"title": "Justicia social", "text": "Transforma desigualdades sociales, económicas y políticas que producen vulnerabilidades diferenciadas."}, {"title": "Adaptabilidad", "text": "Fortalece capacidades para anticipar, responder y ajustarse a los impactos y cambios asociados al clima."}, {"title": "Sostenibilidad", "text": "Cuenta con recursos, capacidades, relaciones o estructuras que favorecen su continuidad en el tiempo."}, {"title": "Replicabilidad", "text": "Genera prácticas, estrategias o aprendizajes que pueden adaptarse y servir en otros contextos."}]}');

INSERT OR IGNORE INTO project_info (section_key, title, content)
VALUES ('guiding_principles', 'Cómo nos relacionamos y contamos cada historia.', '{"eyebrow": "PRINCIPIOS DE TRABAJO", "note": "Cinco principios orientan el trabajo del proyecto con cada comunidad.", "items": [{"title": "Solidaridad", "text": "Construir relaciones de apoyo mutuo, reciprocidad y acompañamiento, reconociendo que las luchas y experiencias pueden ser distintas, pero también pueden fortalecerse unas a otras."}, {"title": "Respeto", "text": "Reconocer las historias, conocimientos, prácticas, prioridades y formas de organización propias de cada comunidad y cultura, evitando imponer agendas, perspectivas o maneras de hacer."}, {"title": "Opacidad", "text": "Reconocer el derecho a no tener que traducirse o hacerse completamente legible o transparente para los demás."}, {"title": "Hibridez", "text": "Reconocer que las iniciativas comunitarias no son homogéneas ni estáticas: se construyen y transforman mediante múltiples relaciones, movilidades e intercambios, incluidas las contribuciones de las diásporas y los vínculos entre quienes permanecen, se desplazan y regresan."}, {"title": "Justicia social, ambiental y climática", "text": "Orientar el trabajo hacia la transformación de las desigualdades sociales, económicas, ambientales y políticas que producen vulnerabilidades diferenciadas, reconociendo que los impactos y las capacidades para responder no se distribuyen de manera equitativa."}]}');
